dice = [
    [3, 4, 5, 5, 5, 5],
    [1, 2, 3, 4, 11, 11],
    [0, 1, 9, 10, 10, 10],
    [7, 7, 8, 8, 9, 10],
    [6, 6, 6, 7, 10, 10]
]

def count_wins(a, b):
    wins = 0
    for va in a:
        for vb in b:
            if va > vb:
                wins += 1
    return wins

for i in range(5):
    w = count_wins(dice[i], dice[(i+1)%5])
    print(f"Die {i} beats die {(i+1)%5}: {w} wins out of 36")
